-- CF-247 Firecrawl priority floor: isolated fixture database (scratch PostgreSQL 16 only, never a Supabase project; see run.sh).
-- Tables carry the live NOT NULL, default and key constraints (read from information_schema on fxcwkweaxjtknorudmwp, 8 Nov 2026) for every column the live functions and the
-- fixtures touch. Unedited live helpers are loaded from live/ in run.sh (md5 checked). The helpers below are stand-ins for pieces the edited functions take as given. Nothing here is live data.
create schema if not exists pipeline; create schema if not exists security; create schema if not exists scholarship; create schema if not exists auth; create schema if not exists fx;
do $$ begin create role anon; exception when duplicate_object then null; end $$;
do $$ begin create role authenticated; exception when duplicate_object then null; end $$;
create function auth.role() returns text language sql stable as $f$ select 'service_role'::text $f$;

create table pipeline.platform_toolset_settings(toolset_key text not null, key text not null, label text not null, help text not null default ''::text, kind text not null,
  value jsonb not null, min_value numeric, max_value numeric, unit text, sort integer not null default 100, reason text, updated_by uuid, updated_at timestamptz not null default now(),
  section text not null default 'Notices'::text, used_by text, primary key (toolset_key, key));
create table pipeline.admin_control_events(id bigint generated by default as identity primary key, area text not null, action text not null, target text,
  detail jsonb not null default '{}'::jsonb, actor uuid, created_at timestamptz not null default now());
create table pipeline.layer2_acquisition_providers(id uuid primary key default gen_random_uuid(), provider_key text not null unique, display_name text not null, adapter_type text not null,
  base_url text, auth_scheme text not null default 'none'::text, capabilities jsonb not null default '{}'::jsonb, request_template jsonb not null default '{}'::jsonb,
  enabled boolean not null default true, priority integer not null default 100, concurrency integer not null default 1, timeout_seconds integer not null default 30,
  change_control_ref text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), billing_config jsonb not null default '{}'::jsonb);
create table pipeline.layer2_provider_attempts(id uuid primary key default gen_random_uuid(), job_id uuid not null, profile_version_id uuid not null, acquisition_provider_id uuid not null,
  attempt_no integer not null, status text not null, metrics jsonb not null default '{}'::jsonb, started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now());
create table pipeline.vendor_credit_observations(id bigint generated by default as identity primary key, provider_id uuid not null, remaining_units numeric not null, plan_units numeric,
  period_end timestamptz, observed_at timestamptz not null default now(), raw jsonb);
create table pipeline.coverage_vendor_usage(id bigserial primary key, acquisition_provider_id uuid not null, units numeric not null, purpose text not null, provider_id uuid, url text,
  at timestamptz not null default now(), on_demand_run uuid);
create table pipeline.firecrawl_budget_refusals(day date not null, grp text not null, reason text not null, n integer not null default 0, last_at timestamptz not null default now(),
  primary key (day, grp, reason));
create table pipeline.firecrawl_refusals_by_provider(day date not null, provider_id uuid not null, grp text not null, reason text not null, n integer not null default 0,
  last_at timestamptz not null default now(), primary key (day, provider_id, grp, reason));
create table pipeline.enrich_plan_runs(id uuid primary key default gen_random_uuid(), provider_id uuid not null, mode text not null, state text not null default 'queued'::text,
  steps jsonb not null, estimate jsonb not null default '{}'::jsonb, actual jsonb not null default '{}'::jsonb, requested_by uuid not null, reason text not null,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table pipeline.platform_health_checks(key text primary key, area text not null, label text not null, status text not null default 'skipped'::text, detail jsonb not null default '{}'::jsonb,
  checked_at timestamptz, duration_ms integer, cadence_minutes integer not null default 10, slow boolean not null default false, sort_order integer not null default 100);
-- svc_fc_spend reads these only for the scholarship and central branches (columns used)
create table scholarship.scholarships(id uuid primary key, provider_id uuid);
create table pipeline.scholarship_pages(scholarship_id uuid, url text, requested_at timestamptz);
create table pipeline.provider_fact_sources(provider_id uuid, url text, status text, read_at timestamptz);
create table pipeline.entry_matrix_sources(provider_id uuid, url text, status text, read_at timestamptz);

-- stand-ins: no directory hosts; every provider eligible; no stop gate; no cost breaker; the vendor budget rule is only reached when no balance is fresh (answers "allowed")
create function security.fc_spend_host_v1(p_url text) returns text language sql immutable as $f$ select substring(p_url from '^https?://([^/]+)') $f$;
create function security.third_party_host_v1(p_url text) returns boolean language sql immutable as $f$ select p_url like '%directory.example%' $f$;
create function security.fc_sch_eligible_v1(p uuid) returns boolean language sql stable as $f$ select true $f$;
create function security.fc_sch_cap_since_v1(p uuid) returns timestamptz language sql stable as $f$ select '-infinity'::timestamptz $f$;
create function security.search_stop_gate_v1(p uuid, p2 uuid default null, p3 boolean default null, p4 boolean default null) returns text language sql stable as $f$ select null::text $f$;
create function security.ops_cost_fc_refusal_v1(p_units numeric, p_purpose text, p_provider_id uuid, p_url text) returns text language sql stable as $f$ select null::text $f$;
create function security.layer2_provider_budget_status(p_provider uuid, p_units numeric) returns jsonb language sql stable as
  $f$ select jsonb_build_object('allowed', true, 'remaining_units', 1000000, 'limit_units', 1000000, 'stop_at_remaining_units', 0) $f$;
